@pytest.mark.parametrize('fault',('native','source','instruction','anchors','alias_present','alias_duplicate','edits_short','edit_missing','edit_duplicate','count_bool','count_wrong','slot_bytes','getter_bytes','alias_extra'))
def test_stale_thing_alias_is_rejected(review_input,fault):
 from tools.script_recovery.native_reviewed_stack_aliases import restore
 from tools.script_recovery.test_native_inline_self_argument import ChangedBytes
 captured,row=review_input;row=copy.deepcopy(row);fn=copy.deepcopy(captured['fn']);text=captured['text'];rd=captured['rd']
 if fault=='native':row['nativeSha256']='0'*64
 elif fault=='source':fn['decompile']+='\n'
 elif fault=='instruction':row['nativeInstructions']['0xecb9fe']='90'
 elif fault=='anchors':row['nativeInstructions']={}
 elif fault=='alias_present':text+='\n'+row['alias']+';'
 elif fault=='alias_duplicate':row['additionalAliases']=[row['alias']]
 elif fault=='edits_short':row['edits']=row['edits'][:1]
 elif fault=='edit_missing':text=text.replace(row['edits'][0][0],'MISSING',1)
 elif fault=='edit_duplicate':text+='\n'+row['edits'][1][0]+';'
 elif fault=='count_bool':row['editCounts']=[True,1]
 elif fault=='count_wrong':row['editCounts']=[2,1]
 elif fault=='slot_bytes':rd=ChangedBytes(rd,{0xecb9fe:bytes.fromhex('ff9028010000')})
 elif fault=='getter_bytes':rd=ChangedBytes(rd,{0xecb1c6:bytes.fromhex('8d44242c')})
 else:row['additionalAliases']=['bad alias']
 with pytest.raises(ValueError,match='reviewed stack alias'):restore(text,fn,row,rd)

